   754		); err != nil {
   755			return commit(err)
   756		}
   757		for _, warning := range header.Warnings {
   758			if err := insertSemanticWarning(tx, warning, "warning"); err != nil {
   759				return commit(err)
   760			}
   761		}
   762		for _, failure := range header.PartialFailures {
   763			if err := insertSemanticWarning(tx, failure, "partial_failure"); err != nil {
   764				return commit(err)
