   766		}
   767	
   768		files := make(map[string]semanticRecord)
   769		scanner := newSemanticScanner(bytes.NewReader(raw))
   770		if !scanner.Scan() {
   771			return commit(errors.New("semantic snapshot missing header"))
   772		}
   773		for scanner.Scan() {
   774			text := bytes.TrimSpace(scanner.Bytes())
   775			if len(text) == 0 {
   776				continue
   777			}
