   779			if err := json.Unmarshal(text, &record); err != nil {
   780				return commit(err)
   781			}
   782			switch record.RecordType {
   783			case "file":
   784				path := record.semanticPath()
   785				if path != "" {
   786					path, err = validateSemanticProviderPath(path)
   787					if err != nil {
   788						return commit(err)
   789					}
   790					record.setSemanticPath(path)
   791					files[path] = record
   792				}
   793			case "symbol":
