   796					path, err = validateSemanticProviderPath(path)
   797					if err != nil {
   798						return commit(err)
   799					}
   800					record.setSemanticPath(path)
   801					if _, ok := files[path]; !ok {
   802						files[path] = semanticRecord{RecordType: "file", FilePath: path}
   803					}
   804				}
   805				if err := insertSemanticSymbol(tx, record); err != nil {
   806					return commit(err)
   807				}
   808			case "relation":
   809				if err := insertSemanticRelation(tx, record); err != nil {
   810					return commit(err)
   811				}
   812			}
   813		}
   814		if err := scanner.Err(); err != nil {
   815			return commit(err)
   816		}
   817	
   818		parseCacheFiles := 0
   819		for path, record := range files {
   820			contentHash := semanticFileContentHash(repoDir, path)
   821			if contentHash == "" && record.Blob != "" {
   822				contentHash = "git-blob:" + record.Blob
   823			}
   824			artifactRel, err := writeSemanticParseCacheArtifact(generationDir, path, record.Blob, contentHash)
   825			if err != nil {
   826				return commit(err)
   827			}
   828			parseCacheFiles++
   829			if _, err := tx.Exec(`INSERT OR REPLACE INTO files(path, blob, content_hash) VALUES (?, ?, ?)`, path, record.Blob, contentHash); err != nil {
   830				return commit(err)
   831			}
   832			if _, err := tx.Exec(`INSERT OR REPLACE INTO parse_cache(path, blob, content_hash, artifact_path) VALUES (?, ?, ?, ?)`, path, record.Blob, contentHash, artifactRel); err != nil {
   833				return commit(err)
   834			}
   835		}
   836	
   837		metrics := semanticBuildMetrics{
   838			GeneratedAt:     now,
   839			GenerationID:    generationID,
   840			Commit:          header.Commit,
   841			Tree:            header.Tree,
   842			Files:           len(files),
   843			Symbols:         counts.Symbols,
   844			Relations:       counts.Relations,
   845			ReverseEdges:    counts.Relations,
   846			Warnings:        len(header.Warnings),
   847			PartialFailures: len(header.PartialFailures),
   848			ParseCacheFiles: parseCacheFiles,
   849		}
   850		metricsJSON, _ := json.Marshal(metrics)
   851		if _, err := tx.Exec(`INSERT OR REPLACE INTO metrics(key, value) VALUES (?, ?)`, "build", string(metricsJSON)); err != nil {
   852			return commit(err)
   853		}
   854		if err := tx.Commit(); err != nil {
   855			return semanticBuildMetrics{}, err
   856		}
   857		return metrics, nil
   858	}
