   919			sum := sha256.Sum256([]byte(path + "\x00" + blob + "\x00" + key))
   920			key = "sha256:" + hex.EncodeToString(sum[:])

Chunk ID: 5956f0
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 3612
Output:
   920			key = "sha256:" + hex.EncodeToString(sum[:])
   921		}
   922		cleanKey := strings.TrimPrefix(key, "sha256:")
   923		if len(cleanKey) < 4 {
   924			cleanKey = hex.EncodeToString([]byte(cleanKey))
   925		}
   926		rel := filepath.Join("parse-cache", cleanKey[:2], cleanKey[2:4], cleanKey+".json")
