  1000	func loadBrainIgnore(repoDir string) (brainIgnore, error) {
  1001		data, err := os.ReadFile(filepath.Join(repoDir, ".brainignore"))
  1002		if err != nil {
  1003			if os.IsNotExist(err) {
  1004				return brainIgnore{}, nil
  1005			}
  1006			return brainIgnore{}, fmt.Errorf("read .brainignore: %w", err)
  1007		}
  1008		var ignore brainIgnore
  1009		for _, line := range strings.Split(string(data), "\n") {
  1010			line = strings.TrimSpace(line)
  1011			if line == "" || strings.HasPrefix(line, "#") {
  1012				continue
  1013			}
  1014			ignore.patterns = append(ignore.patterns, filepath.ToSlash(line))
  1015		}
  1016		return ignore, nil
  1017	}
