  1019	func (i brainIgnore) Ignored(path string) bool {
  1020		path = filepath.ToSlash(strings.TrimPrefix(path, "./"))
  1021		if path == ".git" || strings.HasPrefix(path, ".git/") {
  1022			return true
  1023		}
  1024		for _, segment := range []string{"node_modules", "vendor", "dist", "build", "target", ".entire"} {
  1025			if pathHasSegment(path, segment) {
  1026				return true
  1027			}
  1028		}
  1029		for _, pattern := range []string{".env", ".pem", ".key"} {
  1030			if path == pattern || strings.Contains(path, "/"+pattern) || strings.HasSuffix(path, pattern) {
  1031				return true
  1032			}
  1033		}
  1034		for _, pattern := range i.patterns {
  1035			if pattern == path || strings.HasPrefix(path, strings.TrimSuffix(pattern, "/")+"/") {
  1036				return true
  1037			}
  1038			if ok, _ := filepath.Match(pattern, path); ok {
  1039				return true
  1040			}
  1041		}
  1042		return false
  1043	}
  1044	
  1045	func pathHasSegment(path, segment string) bool {
  1046		for _, part := range strings.Split(path, "/") {
  1047			if part == segment {
  1048				return true
  1049			}
  1050		}
  1051		return false
  1052	}
