  1054	func (i brainIgnore) FilterWarnings(warnings []semanticWarning) []semanticWarning {
  1055		if len(warnings) == 0 {
  1056			return nil
  1057		}
  1058		filtered := make([]semanticWarning, 0, len(warnings))
  1059		for _, warning := range warnings {
  1060			if i.Ignored(warning.Path) || i.MentionsIgnoredPath(warning.Detail) || i.MentionsIgnoredPath(warning.Effect) {
  1061				continue
  1062			}
  1063			filtered = append(filtered, warning)
  1064		}
  1065		return filtered
  1066	}
