  1068	func (i brainIgnore) MentionsIgnoredPath(text string) bool {
  1069		text = filepath.ToSlash(text)
  1070		if text == "" {
  1071			return false
  1072		}
  1073		for _, pattern := range append([]string{".env", ".pem", ".key"}, i.patterns...) {
  1074			pattern = strings.Trim(filepath.ToSlash(pattern), "/")
  1075			if pattern != "" && strings.Contains(text, pattern) {
  1076				return true
  1077			}
  1078		}
  1079		return false
  1080	}
