  1098	func worktreeFingerprint(ctx context.Context, runner CommandRunner, repoDir string) string {
  1099		status, _, _ := runner.Run(ctx, repoDir, "git", "status", "--porcelain")
  1100		diff, _, _ := runner.Run(ctx, repoDir, "git", "diff", "--binary", "HEAD")
  1101		cached, _, _ := runner.Run(ctx, repoDir, "git", "diff", "--cached", "--binary", "HEAD")
  1102		content := append(append(status, diff...), cached...)
  1103		content = appendUntrackedWorktreeContent(content, repoDir, status)
  1104		sum := sha256.Sum256(content)
  1105		return "sha256:" + hex.EncodeToString(sum[:])
  1106	}
