  1108	func appendUntrackedWorktreeContent(content []byte, repoDir string, status []byte) []byte {
  1109		for _, line := range strings.Split(string(status), "\n") {
  1110			if !strings.HasPrefix(line, "?? ") {
  1111				continue
  1112			}
  1113			path := strings.TrimSpace(strings.TrimPrefix(line, "?? "))
  1114			clean, err := validateSemanticProviderPath(path)
  1115			if err != nil {
  1116				continue
  1117			}
  1118			content = appendWorktreePathContent(content, repoDir, clean)
  1119		}
  1120		return content
  1121	}
  1122	
  1123	func appendWorktreePathContent(content []byte, repoDir, clean string) []byte {
  1124		path := filepath.Join(repoDir, filepath.FromSlash(clean))
  1125		info, err := os.Lstat(path)
  1126		if err != nil || info.Mode()&os.ModeSymlink != 0 {
  1127			return content
  1128		}
  1129		if info.IsDir() {
  1130			_ = filepath.WalkDir(path, func(child string, d os.DirEntry, walkErr error) error {
  1131				if walkErr != nil || d.IsDir() {
  1132					return nil
  1133				}
  1134				rel, err := filepath.Rel(repoDir, child)
  1135				if err != nil {
  1136					return nil
  1137				}
  1138				relSlash := filepath.ToSlash(rel)
  1139				if _, err := validateSemanticProviderPath(relSlash); err != nil {
  1140					return nil
  1141				}
  1142				content = appendFileFingerprintContent(content, child, relSlash)
  1143				return nil
  1144			})
  1145			return content
  1146		}
  1147		return appendFileFingerprintContent(content, path, clean)
  1148	}
  1149	
  1150	func appendFileFingerprintContent(content []byte, path, rel string) []byte {
  1151		data, err := os.ReadFile(path)
  1152		if err != nil {
  1153			return content
  1154		}
  1155		content = append(content, "\x00untracked:"...)
  1156		content = append(content, rel...)
  1157		content = append(content, 0)
  1158		return append(content, data...)
  1159	}
