  1225	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
  1226		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
  1227		if err != nil {
  1228			return staleReport{}, err
  1229		}
  1230		if !local {
  1231			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
  1232		}
  1233		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1234		if err != nil {
  1235			return staleReport{}, err
  1236		}
  1237		manifest, err := loadBrainManifest(storage.BrainDir)
  1238		if err != nil {
  1239			return staleReport{}, err
  1240		}
  1241		axes := map[string]staleAxis{}
  1242		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
  1243			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
  1244			return staleReport{Severity: "unsafe", Axes: axes}, nil
  1245		}
  1246		source := manifest.Sources.Semantic
  1247		if source.SnapshotPath == "" {
  1248			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
  1249		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
  1250			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1251		} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
  1252			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1253		} else {
  1254			snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
  1255			snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)
  1256			if snapshotErr != nil {
  1257				axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
  1258			} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
  1259				axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1260			} else {
  1261				axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
  1262			}
  1263		}
  1264		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
  1265		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
  1266		dirty, dirtyErr := worktreeDirty(ctx, opts.Runner, repoDir)
  1267		if source.Commit == head {
  1268			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
  1269		} else {
