  1570		entries, err := os.ReadDir(root)
  1571		if err != nil {
  1572			if os.IsNotExist(err) {
  1573				return 0, nil
  1574			}
  1575			return 0, err
  1576		}
  1577		pruned := 0
  1578		for _, entry := range entries {
  1579			if !entry.IsDir() {
  1580				continue
  1581			}
  1582			path := filepath.Join(root, entry.Name())
  1583			if active != "" && filepath.Clean(path) == active {
