  1603	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
  1604		value = strings.TrimSpace(value)
  1605		if strings.HasSuffix(value, "d") {
  1606			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
  1607			if err != nil || days < 0 {
  1608				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1609			}
  1610			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1611		}
  1612		duration, err := time.ParseDuration(value)
  1613		if err != nil {
  1614			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1615		}
  1616		return now.Add(-duration), nil
  1617	}
